sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.adherence-card{
    background:#fff;
    padding:20px;
    border-radius:16px;
    box-shadow:0 4px 15px rgba(0,0,0,0.08);
}

.section-title{
    margin-bottom:20px;
    color:#1B5E20;
    font-weight:600;
}

.section-title i{
    margin-right:8px;
}

.patient-row{
    margin-bottom:20px;
}

.patient-header{
    display:flex;
    align-items:center;
    margin-bottom:10px;
}

.patient-avatar{
    width:40px;
    height:40px;
    border-radius:50%;
    background:#1B5E20;
    color:#fff;
    display:flex;
    align-items:center;
    justify-content:center;
    font-weight:bold;
    margin-right:12px;
}

.patient-info{
    flex:1;
    display:flex;
    justify-content:space-between;
    align-items:center;
}

.patient-name{
    font-weight:600;
    color:#333;
}

.patient-percent{
    color:#1B5E20;
    font-weight:700;
}

.progress{
    height:12px;
    background:#EAEAEA;
    border-radius:20px;
    overflow:hidden;
}

.progress-bar{
    height:100%;
    background:linear-gradient(
        90deg,
        #1B5E20,
        #4CAF50
    );
    border-radius:20px;
    transition:width .5s ease;
}

